<?php
require_once __DIR__.'/../includes/functions.php';require_admin();$error='';$letters=$pdo->query('SELECT * FROM alphabet ORDER BY sort_order,id')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$id=(int)($_POST['id']??0);$pron=trim($_POST['pronunciation']??'');$example=trim($_POST['example_word']??'');$meaning=trim($_POST['example_meaning']??'');$name=trim($_POST['letter_name']??'');$audio=upload_audio('audio_file','alphabet');if($audio){$s=$pdo->prepare('UPDATE alphabet SET pronunciation=?,example_word=?,example_meaning=?,letter_name=?,audio_path=? WHERE id=?');$s->execute([$pron,$example,$meaning,$name,$audio,$id]);}else{$s=$pdo->prepare('UPDATE alphabet SET pronunciation=?,example_word=?,example_meaning=?,letter_name=? WHERE id=?');$s->execute([$pron,$example,$meaning,$name,$id]);}flash('success','Alphabet entry updated.');redirect('admin/alphabet.php');}catch(Throwable $e){$error=$e->getMessage();}}
$page_title='Manage alphabet';require __DIR__.'/../includes/admin_header.php';
?>
<div class="admin-heading"><div><span class="eyebrow">FOUNDATIONS</span><h1>Alphabet and pronunciation</h1><p>Update examples and add your own audio recordings for each letter.</p></div></div><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="admin-letter-list"><?php foreach($letters as $letter): ?><form method="post" enctype="multipart/form-data" class="admin-panel admin-letter-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$letter['id'] ?>"><div class="admin-letter-mark"><?= e($letter['letter']) ?></div><div class="admin-letter-fields"><div class="form-row"><label>Letter / sound name<input name="letter_name" value="<?= e($letter['letter_name']) ?>"></label><label>Pronunciation guide<input name="pronunciation" value="<?= e($letter['pronunciation']) ?>"></label></div><div class="form-row"><label>Example word<input name="example_word" value="<?= e($letter['example_word']) ?>"></label><label>English meaning<input name="example_meaning" value="<?= e($letter['example_meaning']) ?>"></label></div><label>Replace / upload audio (MP3, WAV, OGG, M4A; max 10 MB)<input type="file" name="audio_file" accept="audio/*"></label><?php if($letter['audio_path']): ?><small>Audio: <a href="<?= url($letter['audio_path']) ?>" target="_blank" rel="noopener">Listen to current file</a></small><?php endif; ?><button class="btn btn-small btn-primary" type="submit">Save <?= e($letter['letter']) ?></button></div></form><?php endforeach; ?></div>
